851:int aom_decode_frame_from_obus(struct AV1Decoder *pbi, const uint8_t *data,
852:                               const uint8_t *data_end,
853:                               const uint8_t **p_data_end) {
854:  AV1_COMMON *const cm = &pbi->common;
855:  int frame_decoding_finished = 0;
856:  int is_first_tg_obu_received = 1;
857:  // Whenever pbi->seen_frame_header is set to 1, frame_header is set to the
858:  // beginning of the frame_header_obu and frame_header_size is set to its
859:  // size. This allows us to check if a redundant frame_header_obu is a copy
860:  // of the previous frame_header_obu.
861:  //
862:  // Initialize frame_header to a dummy nonnull pointer, otherwise the Clang
863:  // Static Analyzer in clang 7.0.1 will falsely warn that a null pointer is
864:  // passed as an argument to a 'nonnull' parameter of memcmp(). The initial
865:  // value will not be used.
866:  const uint8_t *frame_header = data;
867:  uint32_t frame_header_size = 0;
868:  ObuHeader obu_header;
869:  memset(&obu_header, 0, sizeof(obu_header));
870:  pbi->seen_frame_header = 0;
871:  pbi->next_start_tile = 0;
872:  pbi->num_tile_groups = 0;
873:
874:  if (data_end < data) {
875:    cm->error.error_code = AOM_CODEC_CORRUPT_FRAME;
876:    return -1;
877:  }
878:
879:  // Reset pbi->camera_frame_header_ready to 0 if cm->tiles.large_scale = 0.
880:  if (!cm->tiles.large_scale) pbi->camera_frame_header_ready = 0;
881:
882:  // decode frame as a series of OBUs
883:  while (!frame_decoding_finished && cm->error.error_code == AOM_CODEC_OK) {
884:    struct aom_read_bit_buffer rb;
885:    size_t payload_size = 0;
886:    size_t decoded_payload_size = 0;
887:    size_t obu_payload_offset = 0;
888:    size_t bytes_read = 0;
889:    const size_t bytes_available = data_end - data;
890:
891:    if (bytes_available == 0 && !pbi->seen_frame_header) {
892:      *p_data_end = data;
893:      cm->error.error_code = AOM_CODEC_OK;
894:      break;
895:    }
896:
897:    aom_codec_err_t status =
898:        aom_read_obu_header_and_size(data, bytes_available, pbi->is_annexb,
899:                                     &obu_header, &payload_size, &bytes_read);
900:
901:    if (status != AOM_CODEC_OK) {
902:      cm->error.error_code = status;
903:      return -1;
904:    }
905:
906:    // Record obu size header information.
907:    pbi->obu_size_hdr.data = data + obu_header.size;
908:    pbi->obu_size_hdr.size = bytes_read - obu_header.size;
909:
910:    // Note: aom_read_obu_header_and_size() takes care of checking that this
911:    // doesn't cause 'data' to advance past 'data_end'.
912:    data += bytes_read;
913:
914:    if ((size_t)(data_end - data) < payload_size) {
915:      cm->error.error_code = AOM_CODEC_CORRUPT_FRAME;
916:      return -1;
917:    }
918:
919:    cm->temporal_layer_id = obu_header.temporal_layer_id;
920:    cm->spatial_layer_id = obu_header.spatial_layer_id;
921:
922:    if (obu_header.type != OBU_TEMPORAL_DELIMITER &&
923:        obu_header.type != OBU_SEQUENCE_HEADER) {
924:      // don't decode obu if it's not in current operating mode
925:      if (!is_obu_in_current_operating_point(pbi, &obu_header)) {
926:        data += payload_size;
927:        continue;
928:      }
929:    }
930:
931:    av1_init_read_bit_buffer(pbi, &rb, data, data + payload_size);
932:
933:    switch (obu_header.type) {
934:      case OBU_TEMPORAL_DELIMITER:
935:        decoded_payload_size = read_temporal_delimiter_obu();
936:        if (pbi->seen_frame_header) {
937:          // A new temporal unit has started, but the frame in the previous
938:          // temporal unit is incomplete.
939:          cm->error.error_code = AOM_CODEC_CORRUPT_FRAME;
940:          return -1;
941:        }
942:        break;
943:      case OBU_SEQUENCE_HEADER:
944:        decoded_payload_size = read_sequence_header_obu(pbi, &rb);
945:        if (cm->error.error_code != AOM_CODEC_OK) return -1;
946:        // The sequence header should not change in the middle of a frame.
947:        if (pbi->sequence_header_changed && pbi->seen_frame_header) {
948:          cm->error.error_code = AOM_CODEC_CORRUPT_FRAME;
949:          return -1;
950:        }
951:        break;
952:      case OBU_FRAME_HEADER:
953:      case OBU_REDUNDANT_FRAME_HEADER:
954:      case OBU_FRAME:
955:        if (obu_header.type == OBU_REDUNDANT_FRAME_HEADER) {
956:          if (!pbi->seen_frame_header) {
957:            cm->error.error_code = AOM_CODEC_CORRUPT_FRAME;
958:            return -1;
959:          }
960:        } else {
961:          // OBU_FRAME_HEADER or OBU_FRAME.
962:          if (pbi->seen_frame_header) {
963:            cm->error.error_code = AOM_CODEC_CORRUPT_FRAME;
964:            return -1;
965:          }
966:        }
967:        // Only decode first frame header received
968:        if (!pbi->seen_frame_header ||
969:            (cm->tiles.large_scale && !pbi->camera_frame_header_ready)) {
970:          frame_header_size = read_frame_header_obu(
971:              pbi, &rb, data, p_data_end, obu_header.type != OBU_FRAME);
972:          frame_header = data;
973:          pbi->seen_frame_header = 1;
974:          if (!pbi->ext_tile_debug && cm->tiles.large_scale)
975:            pbi->camera_frame_header_ready = 1;
976:        } else {
977:          // Verify that the frame_header_obu is identical to the original
978:          // frame_header_obu.
979:          if (frame_header_size > payload_size ||
980:              memcmp(data, frame_header, frame_header_size) != 0) {
981:            cm->error.error_code = AOM_CODEC_CORRUPT_FRAME;
982:            return -1;
983:          }
984:          assert(rb.bit_offset == 0);
985:          rb.bit_offset = 8 * frame_header_size;
986:        }
987:
988:        decoded_payload_size = frame_header_size;
989:        pbi->frame_header_size = frame_header_size;
990:
991:        if (cm->show_existing_frame) {
992:          if (obu_header.type == OBU_FRAME) {
993:            cm->error.error_code = AOM_CODEC_UNSUP_BITSTREAM;
994:            return -1;
995:          }
996:          frame_decoding_finished = 1;
997:          pbi->seen_frame_header = 0;
998:          break;
999:        }
1000:
1001:        // In large scale tile coding, decode the common camera frame header
1002:        // before any tile list OBU.
1003:        if (!pbi->ext_tile_debug && pbi->camera_frame_header_ready) {
1004:          frame_decoding_finished = 1;
1005:          // Skip the rest of the frame data.
1006:          decoded_payload_size = payload_size;
1007:          // Update data_end.
1008:          *p_data_end = data_end;
1009:          break;
1010:        }
1011:
1012:        if (obu_header.type != OBU_FRAME) break;
1013:        obu_payload_offset = frame_header_size;
1014:        // Byte align the reader before reading the tile group.
1015:        // byte_alignment() has set cm->error.error_code if it returns -1.
1016:        if (byte_alignment(cm, &rb)) return -1;
1017:        AOM_FALLTHROUGH_INTENDED;  // fall through to read tile group.
1018:      case OBU_TILE_GROUP:
1019:        if (!pbi->seen_frame_header) {
1020:          cm->error.error_code = AOM_CODEC_CORRUPT_FRAME;
1021:          return -1;
1022:        }
1023:        if (obu_payload_offset > payload_size) {
1024:          cm->error.error_code = AOM_CODEC_CORRUPT_FRAME;
1025:          return -1;
1026:        }
1027:        decoded_payload_size += read_one_tile_group_obu(
1028:            pbi, &rb, is_first_tg_obu_received, data + obu_payload_offset,
1029:            data + payload_size, p_data_end, &frame_decoding_finished,
1030:            obu_header.type == OBU_FRAME);
1031:        if (cm->error.error_code != AOM_CODEC_OK) return -1;
1032:        is_first_tg_obu_received = 0;
1033:        if (frame_decoding_finished) {
1034:          pbi->seen_frame_header = 0;
1035:          pbi->next_start_tile = 0;
1036:        }
1037:        pbi->num_tile_groups++;
1038:        break;
1039:      case OBU_METADATA:
1040:        decoded_payload_size = read_metadata(pbi, data, payload_size);
1041:        if (cm->error.error_code != AOM_CODEC_OK) return -1;
1042:        break;
1043:      case OBU_TILE_LIST:
1044:        if (CONFIG_NORMAL_TILE_MODE) {
1045:          cm->error.error_code = AOM_CODEC_UNSUP_BITSTREAM;
1046:          return -1;
1047:        }
1048:
1049:        // This OBU type is purely for the large scale tile coding mode.
1050:        // The common camera frame header has to be already decoded.
1051:        if (!pbi->camera_frame_header_ready) {
1052:          cm->error.error_code = AOM_CODEC_CORRUPT_FRAME;
1053:          return -1;
1054:        }
1055:
1056:        cm->tiles.large_scale = 1;
1057:        av1_set_single_tile_decoding_mode(cm);
1058:        decoded_payload_size =
1059:            read_and_decode_one_tile_list(pbi, &rb, data, data + payload_size,
1060:                                          p_data_end, &frame_decoding_finished);
1061:        if (cm->error.error_code != AOM_CODEC_OK) return -1;
1062:        break;
1063:      case OBU_PADDING:
1064:        decoded_payload_size = read_padding(cm, data, payload_size);
1065:        if (cm->error.error_code != AOM_CODEC_OK) return -1;
