568:// Returns the last nonzero byte index in 'data'. If there is no nonzero byte in
569:// 'data', returns -1.
570:static int get_last_nonzero_byte_index(const uint8_t *data, size_t sz) {
571:  // Scan backward and return on the first nonzero byte.
572:  int i = (int)sz - 1;
573:  while (i >= 0 && data[i] == 0) {
574:    --i;
575:  }
576:  return i;
577:}
