579:// Allocates metadata that was read and adds it to the decoders metadata array.
580:static void alloc_read_metadata(AV1Decoder *const pbi,
581:                                OBU_METADATA_TYPE metadata_type,
582:                                const uint8_t *data, size_t sz,
583:                                aom_metadata_insert_flags_t insert_flag) {
584:  AV1_COMMON *const cm = &pbi->common;
585:  if (!pbi->metadata) {
586:    pbi->metadata = aom_img_metadata_array_alloc(0);
587:    if (!pbi->metadata) {
588:      aom_internal_error(&cm->error, AOM_CODEC_MEM_ERROR,
589:                         "Failed to allocate metadata array");
590:    }
591:  }
592:  aom_metadata_t *metadata =
593:      aom_img_metadata_alloc(metadata_type, data, sz, insert_flag);
594:  if (!metadata) {
595:    aom_internal_error(&cm->error, AOM_CODEC_MEM_ERROR,
596:                       "Error allocating metadata");
597:  }
598:  aom_metadata_t **metadata_array =
599:      (aom_metadata_t **)realloc(pbi->metadata->metadata_array,
600:                                 (pbi->metadata->sz + 1) * sizeof(metadata));
601:  if (!metadata_array) {
602:    aom_img_metadata_free(metadata);
603:    aom_internal_error(&cm->error, AOM_CODEC_MEM_ERROR,
604:                       "Error growing metadata array");
